/// One mark, in the colour and size it is asked for.
///
/// Colour defaults to the text colour of whatever it sits in, the same way the
/// demo lets `currentColor` inherit, so a mark inside a dark button needs no
/// special case.
class CalviIcon extends StatelessWidget {
  const CalviIcon(this.name, {super.key, this.size = 22, this.color});

  final String name;
  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final art = calviIcons[name];
    assert(art != null, 'no icon named "$name"');
    final tint = color ?? DefaultTextStyle.of(context).style.color ?? const Color(0xFF000000);

    return SvgPicture.string(
      art ?? '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"/>',
      width: size,
      height: size,
      colorFilter: ColorFilter.mode(tint, BlendMode.srcIn),
    );
  }
}
